def line_total(price, quantity, discount_percent=0):
    # Validate price: must be finite and non-negative
    price_decimal = Decimal(str(price))
    if not price_decimal.is_finite() or price_decimal < 0:
        raise ValueError("Invalid price")

    # Validate quantity: must be non-negative integer (not bool, not float)
    quantity_decimal = Decimal(str(quantity))
    if isinstance(quantity, bool) or not quantity_decimal.is_integer() or quantity_decimal < 0:
        raise ValueError("Invalid quantity")

    # Validate discount_percent: must be finite and in range [0, 100]
    discount_decimal = Decimal(str(discount_percent))
    if not discount_decimal.is_finite() or discount_decimal < 0 or discount_decimal > 100:
        raise ValueError("Invalid discount_percent")

    # Apply discount before rounding
    subtotal = price_decimal * quantity_decimal
    discounted = subtotal * (Decimal('1') - discount_decimal / Decimal('100'))

    # Round to 2 decimal places using ROUND_HALF_UP
    return discounted.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
